INSERT INTO public.address (id, address, postal_code, country, region, city, street, phone_fax, email, website) VALUES ('4ad715fb-d2c9-4510-a1ce-9062ca8486a0', '367026, Российская Федерация, Республика Дагестан, г. Махачкала, проспект Имама Шамиля, 70', '367026', 'Россия', 'Дагестан', 'Махачкала', 'проспект Имама Шамиля, 70', '+7 (8722) 62-37-61', 'dstu@dstu.ru', 'http://www.dstu.ru');
INSERT INTO public.universities (id, name, description, created_at, updated_at, address_id) VALUES ('796c5ad4-52ba-482f-a3bb-31c5de38762d', 'ДГТУ', 'Федеральное государственное бюджетное образовательное учреждение высшего образования «Дагестанский государственный технический университет', '2026-05-12 11:25:11.862205', '2026-05-12 11:25:11.862205', '4ad715fb-d2c9-4510-a1ce-9062ca8486a0');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('9980825f-f630-426a-ac6a-5a185b30f944', 'Факультет компьютерных технологий и энергетики', 'Общество сегодня живет в эпоху внедрения информационных технологий во все сферы человеческой деятельности. Развитие компьютерной техники, IT-технологий, защиты информации, систем управления, электроэнергетики определяет будущее человечества в XXI веке. Потребность в высококвалифицированных кадрах для работы в этих сферах с каждым годом неуклонно растет, благодаря чему факультет компьютерных технологий и энергетики является сегодня одним из самых крупных и наиболее перспективных факультетов ДГТУ.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('3de7d469-96b5-4245-985c-9c6de9591abd', 'Архитектурно-строительный факультет', 'Среди приоритетов развития современной России и Республики Дагестан одним из главных обозначено развитие гармоничного облика современных городов и совершенствование комфортной среды обитания человека. Это во многом зависит от строительной отрасли, от  уровня квалификации, компетентности архитекторов, инженеров-организаторов и управленцев-строителей. Архитектурно-строительный факультет Дагестанского государственного технического университета является одним из передовых и успешных в системе высшего образования республики.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('8964405f-e5f6-4d46-b449-0b2d9e2fe19c', 'Факультет радиоэлектроники и биотехнических систем', 'История факультета и подготовка инженеров радиотехнического профиля в Дагестане началась 1959г., когда в Дагестанском Государственном Университете им.Ленина была открыта специальность «Конструирование и производство радиоаппаратуры» и осуществлен первый набор из 25 студентов. В 1966 г. в ДГУ был образован самостоятельный радиотехнический факультет. При образовании Дагестанского политехнического института в 1972 году одним из основополагающих факультетов был радиотехнический факультет и сегодня он является одним из ведущих факультетов ДГТУ. В феврале 2010 г. радиотехнический факультет был переименован в факультет радиоэлектроники, телекоммуникаций и мультимедийных технологий, а с 2023 года с учетом специфики направлений и специальностей обучения переименован в Факультет радиоэлектроники и биотехнических систем.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('8184655f-ccd1-4da3-802d-08cf2ebf018e', 'Технологический факультет', 'С февраля 2022 года факультет возглавляет Фаина Шамиловна Азимова, к.т.н., доцент. В 1986 году окончила химико-технологический факультет Всероссийского института текстильной и легкой промышленности в г. Москве. В 2006 году защитила диссертацию на соискание ученой степени кандидата технических наук в том же вузе. В 2008 году получила ученое звание доцента. С 2007 по 2012 год работала заведующей кафедрой  технологии легкой индустрии  на технологическом  факультете ДГТУ. С 2018 по 2022 год являлась заместителем декана по учебной работе. Является автором более 90 научных работ.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('eee56c9d-1692-4ed9-b27e-9e73ab87c647', 'Факультет нефти, газа и природообустройства', 'Факультет нефти, газа и природообустройства является одним из самых перспективных факультетов Дагестанского государственного технического университета. Современная учебно-лабораторная база, высококвалифицированный профессорско-преподавательский состав, позволяют факультету обеспечить подготовку специалистов высокого уровня, востребованных как в РД, так и далеко за его пределами. ', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('77bc3fb5-68d5-45b8-a75d-4a6a225c67af', 'Факультет дополнительного образования и профессионального обучения', 'Факультет основан в 2004 году и располагает мощной материально технической базой для обучения руководящих работников и специалистов по программам повышения квалификации и переподготовки в соответствии с основными образовательными программами вуза.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('6c8b48fe-f3ad-4152-b626-d919719257f9', 'Заочный факультет', 'Заочный факультет располагает современной учебно-лабораторной базой для подготовки высококвалифицированных специалистов. При факультете функционируют: Центр современных информационных технологий, Интернет-центр, более 20 компьютерных залов.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('ffe0a78a-cadc-475e-9e5f-ac03828dec62', 'Факультет информационных систем в экономике и управлении', 'Факультет информационных систем в экономике и управлении создан приказом № 402 от 06.09.2021 года ДГТУ на базе одних из ведущих, перспективных и активно развивающихся факультетов Дагестанского государственного технического университета: инженерно-экономического факультета и факультета информационных систем, финансов и аудита. Приказом № 194 от 22.05.2025 г. к факультету дополнительно была закреплена кафедра прикладной информатики в юриспруденции.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.faculties (id, name, description, university_id) VALUES ('2764db94-7ce9-46e4-8663-a398afdd878b', 'Факультет среднего профессионального образования', 'Факультет среднего профессионального образования (ФСПО) является структурным подразделением ФГБОУ ВО «Дагестанский государственный технический университет» (ДГТУ), созданным приказом Ректора университета, на основании решения Учёного совета университета от 10.09.2021 года.', '796c5ad4-52ba-482f-a3bb-31c5de38762d');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('9465f482-87b3-41c2-8557-d6c654b87a5a', 'Кафедра прикладной математики и информатики', 'Кафедра прикладной математики и информатики была создана в 1974 году под названием «Кафедра прикладной математики и вычислительной техники» с целью усиления подготовки инженерных кадров во вновь созданном тогда политехническом институте в области использования электронно-вычислительной техники в различных отраслях народного хозяйства. В связи с созданием в институте отдельной кафедры вычислительной техники в 1993 году кафедра была переименована в кафедру «Прикладной математики», позднее - в кафедру информатики., а с 2012 года- в кафедру прикладной математики и информатики.', '9980825f-f630-426a-ac6a-5a185b30f944');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('86afb4e7-c29c-4369-b87d-ff1905a80a96', 'Кафедра электроэнергетики и возобновляемых источников энергии', 'Широкое применение электрической энергии во всех областях деятельности человека делает актуальным вопрос производства электрической энергии, а также проектирования, создания и обслуживания новых электростанций. Дагестан является одним из основных производителей электрической энергии на Северном Кавказе, получаемой с помощью гидроэлектростанций. Дагестанскими энергетиками построен целый каскад гидроэлектростанций, которые являются основными производителями электрической энергии, и в ближайшем будущем предполагается строительство еще нескольких электрических станций, в том числе и станций с использованием нетрадиционных источников энергии.', '9980825f-f630-426a-ac6a-5a185b30f944');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('b96522c1-4607-46ab-b817-4b662ec5b85a', 'Кафедра теоретической и общей электротехники', 'Кафедра теоретической и общей электротехники была создана в 1972 году в результате структурных преобразований кафедры теоретических основ радиотехники, которой руководил доцент К.М. Мамаев.', '9980825f-f630-426a-ac6a-5a185b30f944');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('d1282b11-4caf-4ed7-8ecb-984e2f7d2305', 'Кафедра информационной безопасности и программной инженерии', 'Спрос на специалистов по защите информации на рынке труда превышает предложение и востребованность специалистов обусловило создание в 2017 году на факультете кафедры информационной безопасности. С увеличением зависимости общества от цифровых технологий спрос на квалифицированных специалистов в области информационной безопасности стабильно высок. В 2024 году только на портале «Работа России» было открыто более 1500 вакансий по специальности «Информационная безопасность». Выпускники занимают позиции аналитиков, инженеров по информационной безопасности, менеджеров по рискам и аудиторов.', '9980825f-f630-426a-ac6a-5a185b30f944');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('d7bf69a7-5ce4-426e-99fa-ce882af1fcce', 'Кафедра управления и информатики в технических системах и вычислительной техники', 'Кафедра управления и информатики в технических системах и вычислительной техники (УиИТСиВТ) создана на базе кафедры управления и информатики в технических системах и вычислительной техники в 2015 году с целью подготовки высококвалифицированных кадров в области информатики и вычислительной техники и управления и информатики в технических системах.', '9980825f-f630-426a-ac6a-5a185b30f944');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('5536af06-0290-4817-bb18-aa2692b4710b', 'Кафедра технологии и организации строительного производства', 'В 1958 году в составе инженерно-технического факультета Дагестанского государственного университета была создана  кафедра «Строительное дело», которая и стала родоначальницей кафедры «Технология и организация строительного производства». Первым заведующим кафедрой «Строительное дело» был заслуженный строитель ДАССР Амирханов Ш.И.', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('ed7c23df-8bde-4919-b337-3e41953c4574', 'Кафедра строительных конструкций и гидротехнических сооружений', 'Кафедра строительных конструкций и гидротехнических сооружений (СКиГТС) была создана в 1973 году под руководством  к.т.н., доцента Юсупова А.К. Абусупьян Юсупов и по сей день трудится на благо кафедры, является не только выдающимся ученым, доктором технических наук, профессором, но и талантливым поэтом и писателем.', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('0d28f3c7-acdb-4039-931d-99621a0c2170', 'Кафедра архитектуры', 'Кафедра архитектуры как выпускающая для специальности «Архитектура» была создана в 2007 году на базе кафедры архитектурного проектирования, начертательной геометрии и геодезии. Зарождение кафедры началось в 1977 году, когда при кафедре строительных конструкций был создан «Курс архитектуры». Заведующим курсом был назначен к.т.н. Магомедов М.Г. В тот период на кафедре работали такие известные архитекторы, как Скугарев В.К., Кутиев Х.Н. В 1980 году на базе данного курса была организована кафедра архитектуры, которую до 1990 года возглавлял к.т.н., доцент Придаткин М.И. В этот период на кафедре преподавательской деятельностью занимались кандидаты наук, доценты Гасангусейнов М.Г., Абдуллаев А.А., Керимов К.Д., Магомедов А.М., Хачалов Г.Б., ст. преподаватель Абдуллаев К.Б. Ими была создана хорошая учебно-методическая и информационная база кафедры. После ухода Придаткина М.И. кафедру возглавил Гасангусейнов М.Г., которому удалось за короткий срок поднять уровень материально-технического обеспечения кафедры. В 1995 году кафедра архитектуры была объединена с кафедрой начертательной геометрии и геодезии и стала называться кафедрой архитектурного проектирования, начертательной геометрии и геодезии (АП,НГиГ). Возглавил кафедру к.т.н., доцент Магомедов А.М. В 2007 году в университете была открыта новая специальность «Архитектура», в связи с чем на базе кафедры АП, НГиГ была открыта кафедра архитектуры, ставшей выпускающей по специальности «Архитектура». С 2009 года кафедру возглавлял д.т.н., профессор, Заслуженный деятель науки Республики Дагестан, Почетный работник ВПО РФ Абакаров АбакарДжансулаевич.', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('62f01bb5-84e0-4eca-b488-8d9edc10864d', 'Кафедра транспортных сооружений и строительных материалов', 'Кафедра «Транспортные сооружения и строительные материалы» создана в сентябре 2021 года на базе двух кафедр: «Автомобильные дороги, основания и фундаменты» и «Строительные материалы и инженерные сети». Заведует кафедрой доктор технических наук, профессор, заслуженный деятель науки РД Агаханов Элифхан Керимханович. В связи с оптимизацией деятельности университетав мае 2025 года с кафедрой «Транспортные сооружения и строительные материалы» объединили кафедру «Организация и безопасность движения».', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('f9135bfd-9900-4045-9114-5eaf1f7b8a37', 'Кафедра русского языка', 'Кафедра русского языка функционирует с 2004 года. Ее коллектив – доктор и кандидаты наук в области лингвистики, известные не только в Дагестане и России, но и за рубежом. Цель деятельности кафедры – пропаганда русской языковой культуры как ключевого фактора единения народов современной России.', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('7b14aed4-a4b5-46a5-a937-8777d6816b61', 'Кафедра физической культуры и спорта', 'Кафедра физической культуры и спорта является одной из старейших в университете, основанной одновременно с вузом в 1972 году. На протяжении всей своей истории она играет ключевую роль в формировании не только физически крепких, но и гармонично развитых, волевых специалистов.Особой гордостью кафедры является плеяда выдающихся руководителей, заложивших высокую профессиональную и спортивную планку. Её возглавляли легенды дагестанского и мирового спорта: · С.А. Эфендиев - заслуженный мастер спорта СССР по вольной борьбе. · Ю.А. Шахмурадов -  заслуженный мастер спорта СССР, заслуженный тренер СССР, доктор технических наук, профессор. · А.Г. Куршалиев -  заслуженный тренер России.', '3de7d469-96b5-4245-985c-9c6de9591abd');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('21d0d071-42c7-4302-9629-7ddfb2166bc9', 'Кафедра радиотехники, телекоммуникаций и микроэлектроники', 'Кафедра радиотехники, телекоммуникаций и микроэлектроники (РТиМ) по основному научно-педагогическому составу и учебно-лабораторному потенциалу является преемницей кафедры «Конструирование и производство радиоаппаратуры», открытой в 1963 году как выпускающая для одноименной специальности, подготовка по которой началась в 1959 году в ДГУ им. В.И. Ленина.', '8964405f-e5f6-4d46-b449-0b2d9e2fe19c');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('5abb8647-6e4c-4f5a-b7b4-07bfac9e0c88', 'Кафедра физики', 'Кафедра физики создана в 1972 году на базе кафедры физики филиала Ленинградского кораблестроительного института. В состав кафедры были приглашены выпускники Московского физико-технического института Стеблин В.И., Стеблина Е., Погорельский К.Н., Маринченко Е.И. На кафедре также работали сотрудники института физики и сотрудники Дагестанского фил. АН СССР Гасанов С.А., Закиев Ю.Э., Саруханов В.У., Шарапудинов М.Р., Исабеков И.М., Абдуллаев Г.А., которые внесли большой вклад в становление кафедры физики и электроники.', '8964405f-e5f6-4d46-b449-0b2d9e2fe19c');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('106d739a-edb8-4e8d-8e8a-8fd28a40c4e0', 'Кафедра биотехнических и медицинских аппаратов и систем', 'Кафедра биотехнических и медицинских аппаратов и систем (БиМАС) создана  в 2006 г. на базе кафедры радиотехники и биомедицинской электроники. Кафедра является выпускающей и ведет подготовку бакалавров по направлениям: 11.03.02 «Инфокоммуникационные технологии и системы связи», по профилю – «Системы мобильной связи», 12.03.04 «Биотехнические системы и технологии», по профилю - «Биотехнические и медицинские аппараты и системы». Предпосылкой для открытия кафедры послужило то, что в ДГТУ с 1990г. плодотворно занимались разработкой электронных изделий медицинского назначения.', '8964405f-e5f6-4d46-b449-0b2d9e2fe19c');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('df36ebe3-71d9-4f0e-a5f2-92ef97e24a4d', 'Кафедра химии', 'Кафедра химии была основана в 1972 г. С 1972 по 1979 гг. кафедру возглавлял д.б.н., профессор Исмаилов Э.Ш., область научных интересов которого является «Действие электромагнитных полей и излучений». Им опубликовано более 300 научных работ, 5 монографий, 8 патентов на изобретения. С 1979 по 1983 г. заведовал кафедрой химии д.т.н., профессор Алиев З.М., область научных интересов которого являлась «Электрохимические технологии под давлением».', '8184655f-ccd1-4da3-802d-08cf2ebf018e');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('48d53934-558f-4bd4-aca0-ff3fa3d8fecb', 'Кафедра технологии пищевых производств, общественного питания и товароведения', 'Кафедра технологии пищевых производств, общественного питания и товароведения образована в сентябре 2017 г. на базе кафедр технологии продукции и организации общественного питания, которую возглавляла д.т.н. Демирова А.Ф. и товароведения и экспертизы (зав. каф. д.т.н. Ахмедов М.Э.). В 2018 году к кафедре ТППОПиТ была присоединена кафедра технологии безалкогольных производств и виноделия (зав. каф., Председатель совета директоров ЗАО ВКЗ ''Избербашский'' Абдулаев М.С.). Эти кафедры были организованы в разное время с 2004 по 2013 гг. в результате упразднения кафедры технологии и машин, созданной в 1976 году.', '8184655f-ccd1-4da3-802d-08cf2ebf018e');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('d76edda8-f468-484d-8fa4-e0a2f52c9092', 'Кафедра гуманитарных наук', 'Кафедра «Гуманитарные науки» создана в начале 2025 года на основе объединения кафедр философии, истории Отечества и Психологии и социо-культурного сервиса. Кафедру возглавил доктор философских наук, профессор Абдулкадыров Юсуп Нурмагомедович. Состав кафедры «Гуманитарные науки»: д.ф.н., профессор Шайдаева Гульнара Магомедовна, д.фил.н., профессор Сулаева Жанна Абдулгамидовна, д.полит.н., доцент Мирзаханов Джабраил Гасанович, к.и.н., доцент Шамхалов Шамиль Шахназарович, к.ф.н., доцент Муртузова Заира Магомедовна, к.и.н., доцент Шихалиева Дагмара Сергоевна, к.ф.н., доцент Нурилова Альбина Захарьяевна, к.и.н., доцент Акимова Аида Акимовна, к.и.н., доцент Гамзаева Гюльнара Шахнавазовна, к.э.н., доцент Курбанова Аксана Джамалутдиновна, к.и.н., старший преподаватель Газимагомедов Рамазан Ибакович, к.и.н., старший преподаватель Казакбиева Ольга Ивановна, к.и.н., старший преподаватель Ремиханова Рамила Идрисовна, к.э.н., старший преподаватель Идрисова Нателла Лукмановна, к.фил.н., старший преподаватель Гасанова Патимат Абдулмукминовна, к.п.н., старший преподаватель Гайдарова Людмила Играмудиновна, к.соц.н., старший преподаватель Шихмамедова Джамиля  Магомедовна, к.п.н., старший преподаватель Мустафаева Аида Рафиковна, старший преподаватель Бабаева Джамиля Везирхановна', '8184655f-ccd1-4da3-802d-08cf2ebf018e');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('2c22f26d-ac13-46b5-822a-0ccd3dfedeed', 'Кафедра ''Дизайн''', 'Кафедра «Дизайн», создана на базе структурного подразделения Дагестанского государственного технического университета «Курс Дизайн», который  был создан в 2015 году с целью подготовки специалистов в области визуальных коммуникаций в рамках профилей профессиональной подготовки Дизайна среды и Дизайн Мультимедиа, для насыщения рынка услуг профессионалами высокого уровня.', '8184655f-ccd1-4da3-802d-08cf2ebf018e');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('3810208c-180b-422a-b542-9077c7fdf0a5', 'Кафедра мелиорации, землеустройства и кадастров', 'В 1976 году была образована кафедра гидромелиорации. Первой заведующей кафедрой была к.с-х.н., доцент Дудникова Л. Г., приглашенная из Новочеркасского инженерно-мелиоративного института; с 1979 по 1993 гг. кафедру возглавлял к.т.н., профессор Муслимов В.Х. С сентября 1994 по 2003 гг. кафедру, переименованную в кафедру гидротехнического строительства, возглавлял д.т.н., профессор Сулейманов И.А.-Г. В 2004 г. была воссоздана кафедра мелиорации, рекультивации и охраны земель, которую возглавил руководитель Минмелиоводхоза РД, д.э.н., профессор Айдамиров Д.С., работающий в ДГТУ с 2004 г. Айдамиров Д.С. является академиком Академии водохозяйственных наук, Заслуженным мелиоратором РФ, награжден «Орденом мужества». С сентября 2020 г. кафедру мелиорации, землеустройства и кадастров возглавлял руководитель ФГБУ «Минмелиоводхоз РД», к.э.н. Курбанов З.М. С сентября 2021 года кафедру возглавляет заместитель заведующего кафедрой МЗиК к.т.н., доцент Курбанова З.А.', 'eee56c9d-1692-4ed9-b27e-9e73ab87c647');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('7f4569f2-35b6-468a-bfb3-15f006c3e3ff', 'Кафедра защиты в чрезвычайных ситуациях', 'Кафедра защиты в чрезвычайных ситуациях создана на базе кафедры экологии и безопасности жизнедеятельности, организованной в 1999 г. Заведующим кафедрой с 1999 по 2005 гг. был к.г.н. Юсуфов С.К. С апреля 2005 года ее возглавлял начальник Главного управления МЧС России по РД, генерал Гаджиев М.М., а с апреля 2010 года его сменил начальник Главного управления МЧС России по РД, генерал-майор Казимагамедов Н.М. В настоящее время кафедрой ЗвЧС возглавляет заместитель заведующего кафедрой, старший преподаватель Месробян Н.Х.', 'eee56c9d-1692-4ed9-b27e-9e73ab87c647');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('9bc4b343-22b7-40ec-98ad-49fa06674961', 'Кафедра нефтегазового дела', 'В целях обеспечения системного подхода в обучении специалистов по нефтегазовому делу, для активизации научно-исследовательской работы кафедр в 2021 году на базе кафедр ''Эксплуатация и обслуживание объектов транспорта и хранения нефти, газа и продуктов переработки'' и ''Бурение нефтяных и газовых скважин'' создана кафедра ''Нефтегазовое дело''.', 'eee56c9d-1692-4ed9-b27e-9e73ab87c647');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('11225ccb-e8a2-4727-859d-9df2bbb67fac', 'Кафедра высшей математики', 'Кафедра высшей математики функционирует с момента открытия Дагестанского политехнического института в 1972 г. Основал кафедру и бессменно её возглавлял до своей скоропостижной кончины в 1991 году доктор физико-математических наук, профессор Халид Шавруханович Мухтаров. Ученый-математик, Заслуженный деятель науки и Заслуженный учитель ДАССР был известен не только в Дагестане и в России, но и за рубежом.', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('dae9f020-467e-4e8f-8db9-d6c111b71d79', 'Кафедра иностранных языков', 'Кафедра ИЯ укомплектована квалифицированными преподавателями, имеющими большой педагогический стаж работы. В штат кафедры входят 13 преподавателей, среди которых 1 профессор (Абуева Н.Н.), 7 доцентов (Магомедова Н.А., Агасиева И.Р., Гасанова Р.Г., Алигаджиева А.Р., Темирханова З.Б., Исаева Р.И., Авчиева Д.Т.)  8 кандидатов наук (Абуева Н.Н., Магомедова Н.А., Агасиева И.Р., Темирханова З.Б., Авчиева Д.Т., Исаева Р.И., Сулейманова Т.А., Алигаджиева А.Р.), 5 старших преподавателей (Сулейманова Т.А., Арчилаева А.Ш., Исмаилова А.Х., Мамедова Г.Б., Ахмедова З.Т.). Руководит кафедрой кандидат филологических наук, профессор Абуева Нажават (Жанна) Надыровна.', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('c79b9679-7eb3-4ce4-b02e-ad07a0000877', 'Кафедра информационных технологий и прикладной информатики в экономике', 'Кафедра информационных технологий и прикладной информатики в экономике создана в 1995 году на базе курса, организованного для специальности 071900 – Информационные системы в экономике, существовавшей в вузе с 1993 года.', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('b73e690b-c413-47cf-bc33-ba5272f2a1c0', 'Кафедра экономики и управления', 'Кафедра экономики и управления создана в 2025 году на базе двух кафедр ''Экономики и управления на предприятии'' и ''Государственного и муниципального управления''.  Она имеет богатую историю и является одной из ключевых выпускающих кафедр университета. Ее истоки восходят к 1972 году, когда на базе кафедры экономики судостроительной промышленности Каспийского филиала ЛКИ была создана кафедра экономики, организации и планирования производства Дагестанского политехнического института.  В 1993 году на базе вуза была открыта выпускающая кафедра для специальности «Государственное и муниципальное управление».', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('af195498-9029-4ffe-89ab-ad6c031429f2', 'Кафедра прикладной информатики в юриспруденции', 'Кафедра «Прикладная информатика в юриспруденции» была создана в 2006г. Заведующий кафедрой «Прикладная информатика в юриспруденции» является Омаров Мухтар Далгатович, к.ю.н., доцент, Руководитель ГКУ «Дирекция по материально-техническому обеспечению мировых судов Республики Дагестан», Генерал-лейтенант юстиции. Он внес огромный вклад в развитие и внедрение информационных систем в судебной деятельности, и использовал опыт внедрения информационных технологий в судопроизводстве в образовательной деятельности и практической подготовке обучающихся по направлению «Прикладная информатика» профиля «Прикладная информатика в юриспруденции».', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('4cbe2a7d-2d6b-4ff9-ba11-5fd0977c6c61', 'Кафедра экономической безопасности, бухгалтерского учета и финансов', 'Кафедра «Экономическая безопасность, бухгалтерский учет и финансы»  создана в 2025 году  во исполнение приказа  ректора ДГТУ №349 от  04.09.2025 г.,  на основании объединения кафедр «Финансы, аудит и  бухгалтерский учет», «Экономическая  теория», «Экономическая безопасность и таможенное дело».', 'ffe0a78a-cadc-475e-9e5f-ac03828dec62');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('a97f7932-4587-4a2f-99e0-3efbacfc6a1a', 'Отделение информационных технологий', 'Отделение информационных технологий создано приказом ректора университета от 10.07.2023 года на основании решения Учёного совета университета и является структурным подразделением факультета СПО ДГТУ.', '2764db94-7ce9-46e4-8663-a398afdd878b');
INSERT INTO public.departments (id, name, description, faculty_id) VALUES ('434c747e-d5c9-427f-ae91-c88130d89d7d', 'Отделение общеобразовательных дисциплин', 'Отделение общеобразовательных дисциплин создано приказом ректора университета от 10.07.2023 года на основании решения Учёного совета университета и является структурным подразделением факультета СПО ДГТУ.', '2764db94-7ce9-46e4-8663-a398afdd878b');
INSERT INTO public.programs (id, faculty_id, code, name, profession, direction, education_level, education_form, duration_of_study, qualification, created_at, updated_at) VALUES ('89a20203-fb4a-4520-a140-96175454e1ab', '3de7d469-96b5-4245-985c-9c6de9591abd', '08.02.01', 'Строительство и эксплуатация зданий и сооружений', 'Строительство и эксплуатация зданий и сооружений', 'Строительство и эксплуатация зданий и сооружений (на базе 9 классов)', 'Среднее профессиональное образование - программы подготовки специалистов среднего звена', 'FULL_TIME', '3 years 10 months', 'Техник', '2026-05-15 12:33:56.223027', '2026-05-15 12:33:56.223027');
